svg.script:
var details, svg;
function init(evt){
  details = document.getElementById('details').firstChild;
  svg = document.getElementsByTagName('svg')[0];
}
function find_child(p, name){
  var ch = p.childNodes;
  for (var i=0; i<ch.length; i++){ if (ch[i].tagName == name) return ch[i]; }
  return null;
}
function g_to_text(e){ var t = find_child(e, 'title'); return t ? t.firstChild.nodeValue : ''; }
function s(node){ details.nodeValue = 'Function: ' + g_to_text(node); }
function c(){ details.nodeValue = ' '; }
function orig_save(e, a){
  if (e.attributes['_orig_'+a] != undefined) return;
  if (e.attributes[a] == undefined) return;
  e.setAttribute('_orig_'+a, e.attributes[a].value);
}
function orig_load(e, a){
  if (e.attributes['_orig_'+a] == undefined) return;
  e.attributes[a].value = e.attributes['_orig_'+a].value;
  e.removeAttribute('_orig_'+a);
}
function zoom(node){
  var ra = find_child(node, 'rect').attributes;
  var width = parseFloat(ra['width'].value);
  var xmin = parseFloat(ra['x'].value);
  var xmax = xmin + width;
  var ratio = (svg.width.baseVal.value - 20) / width;
  var el = document.getElementsByTagName('g');
  for (var i=0; i<el.length; i++){
    var e = el[i], r = find_child(e, 'rect');
    if (!r) continue;
    var ex = parseFloat(r.attributes['x'].value), ew = parseFloat(r.attributes['width'].value);
    if (ex >= xmin - 0.1 && ex + ew <= xmax + 0.1){
      orig_save(r, 'x'); orig_save(r, 'width');
      var nx = (ex - xmin) * ratio + 10;
      r.attributes['x'].value = nx;
      r.attributes['width'].value = ew * ratio;
      var t = find_child(e, 'text');
      if (t){ orig_save(t, 'x'); t.attributes['x'].value = nx + 3; }
      e.style['display'] = 'block';
    } else { e.style['display'] = 'none'; }
  }
  document.getElementById('unzoom').style['opacity'] = '1';
}
function unzoom(){
  var el = document.getElementsByTagName('g');
  for (var i=0; i<el.length; i++){
    var e = el[i]; e.style['display'] = 'block';
    var r = find_child(e, 'rect'); if (r){ orig_load(r, 'x'); orig_load(r, 'width'); }
    var t = find_child(e, 'text'); if (t){ orig_load(t, 'x'); }
  }
  document.getElementById('unzoom').style['opacity'] = '0';
}
